// ECHO — update notices (desktop app).
// Asks the desktop shell whether a newer release is out, shows it on the title
// screen and in the pause menu, and after an update says what changed.
(function () {
  const ECHO = window.ECHO;
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  // What each version brought, newest first. Shown once after updating.
  const CHANGES = [
    { v: '0.23.4', items: [
      'E no longer gets stuck on "Tame … — your den is full". When there is no room to tame a beast (your den is full, or you keep all you may of its kind), its prompt never takes E from a door, a chest, a person or anything else; it only shows when there is nothing else here.',
      'A beaten beast behind a wall or a shut door no longer offers to be tamed "from here": you have to be able to see it.',
      'On the leash (L) with your den full, the leash spares nothing: what you strike down dies, since there is nowhere to put it. You are told once, and making room (U) brings the leash back.',
      'Nothing in your save changes.'
    ] },
    { v: '0.23.3', items: [
      'Fixed the freeze where the screen filled with red and the game stopped dead. A monster that had grown into a summoner (a spider empress, a broodmother, a goblin king, a bone lord, a rat king…) called up its kind, and what it called up could be born as a summoner too. They called up more the moment they appeared, so in a single frame a floor could fill with twenty thousand spiders. The red was their life bars.',
      'Now what a monster calls up is born as it is: never in a higher form, and never a summoner itself. There are never more than two dozen called-up creatures about one place, and summoning stops altogether when 160 creatures are about.',
      'Close the game and open it again if it is frozen now: the swarm is not saved, and the floor comes back as it should. Nothing in your save is lost.'
    ] },
    { v: '0.23.2', items: [
      'A great beast you have beaten down (Thunderhoof the Storm Elk, Gorehorn, the dragons) can be killed now. Strike it once more as it lies beaten and it dies, and you take its hoard: hide, fangs, gold, gear and relics (and scales, from a dragon). Before, blows did nothing to it and E always bound it, so you could only tame it or watch it get up and leave.',
      'E still binds it if you want it for your own. The prompt now says both: "Bind it — or strike it to finish it".',
      'The blow that knocks it down doesn\'t count: the kill only comes from a blow a moment later, so the rest of a combo can\'t decide for you. Your companions\' and beasts\' blows never finish it; only yours do.',
      'Taming on the leash (L) still means taming: then your blows do nothing to it and it waits for you to bind it.',
      'If you already keep four beasts, the choice to make room now also offers "Finish it".'
    ] },
    { v: '0.23.1', items: [
      'Smoother play, above all on a big round world. The game no longer stalls for a moment when the world changes somewhere.',
      'The map: when the land changed (a site dug, a village founded, a wood grown, a house built), the whole world map used to be painted again, which on a round world took a second or more. Now only the part that changed is painted again. After loading, the map is painted around you first and the rest a little at a time.',
      'The guide: when you leave the route (dodging about in a fight, say), only the way back onto it is planned again, not the whole route across the world. Far from your goal that used to cost a tenth of a second every few seconds. Long routes are planned more cheaply, and a goal that only shifts a little (the nearest unexplored country) keeps its route.',
      'Great beasts, gates and floating islands: their roosts and stones are no longer rebuilt every time a tree is felled somewhere in the world.',
      'River currents and ferries are worked out again only when the water changes or you travel well away, not every time the land changes.',
      'Midnight: the day\'s work is lighter. The dungeons ask after the guild once, not once per dungeon. Each crown looks through its people once. The danger of each town\'s country is worked out once a day, not once per person. The heaviest steps went from up to a tenth of a second to a few hundredths.',
      'Your ranks: the share of the land you have walked is counted again only when you walk more, and the nearest unexplored country is looked for again only when you have moved on.',
      'Townsfolk: where people can stand and pass is remembered between their routes until the land changes there.',
      'Nothing in your save changes, and nothing restarts.'
    ] },
    { v: '0.23.0', items: [
      'Danger is fixed to the land now, not to you. The country round the old capitals and the temple is gentle (level 1 to a few). The farther you go from them, the deadlier it gets, and hills, swamps and deep forest are worse than open country, while farmland is a little safer. Walk back to the meadows you started in and they are as gentle as they were. Go far and the land is stronger than you until you grow into it. Out in the far lands it runs from the twenties to past a hundred.',
      'You can see it. Entering a region shows its danger band and what it means for you ("Danger: level 4–9 — easy for you", or "far beyond you"). The place name at the top of the screen shows the danger where you stand. On the world map, zoomed in, every region is labelled with its levels, coloured by how hard it is for you.',
      'What stopped following your level: monsters in the open world (they used to rise to meet you; now they are as strong as where they live), the deep woods (fixed at 70, 150, 300 and 480), the titans (they grow with the years, no longer past you), the giant troll events and the lurkers in wild water. Dungeons and lands already went by distance and still do.',
      'The people of the realm: the rank and file (soldiers, guards, hunters) grow with the years and with the country they live in, so a garrison far out is tougher than one by the capital. The elite still keep pace with you: rival adventurers, the Marshals and Champions of every crown, and the famous of the Guild.',
      'More kingdoms. Each old kingdom has lost a far province, which is now a duchy, principality or free city of its own, with its own ruler, garrison and grudge. The far lands belong to realms of their own peoples: the Kesh to the east, the Auren to the west, the Norren to the north, the Sarrad to the south. Each is a kingdom, khanate, principality, duchy, free city or clan lands, with rulers titled to match (King, Duke, Prince, Khan and Khatun, Doge, High Chief). A new village in the far lands joins the nearest realm or starts one.',
      'Real diplomacy. Every day each pair of powers grows warmer or colder, depending on whether they share a border, a people, an alliance, a truce, a marriage or trade, a claim on each other\'s towns, a common enemy, and on their rulers\' tempers and whether their people are hungry. Borders have incidents (raided herds, turned-back envoys). Trust brings alliances, and alliances lapse when the trust goes. Neighbours swear truces for a season.',
      'The strong make demands of the weak: give back a town we claim, pay tribute for forty days, or bend the knee and be our vassal. Refusing means war. Wars have aims (a claim, plunder, conquest, taking back what broke away, freedom, cutting a giant down to size), and allies are called to arms. An ally that will not come breaks the alliance, but a sworn truce is kept.',
      'Vassals pay tribute, march in their overlord\'s wars and are defended by it, and throw it off when it weakens or the bond sours. A small realm in fear looks for a protector. When one power grows too great, the others band together against it. A realm of twelve towns proclaims itself an empire.',
      'Wars end with terms. Battles won and towns taken count, and when the war wears on, the loser cedes a town it holds that the winner claims, or pays tribute, and a truce follows. A realm stretched too wide may lose a town, most often one it took by the sword: its lord crowns himself, or the fallen house it was taken from raises its old banner again.',
      'The Journal has a new page, "The powers of the world": every realm with its ruler, towns, strength, overlord, allies and wars and how it stands with you; who is friendly with whom; and the latest news between the powers. Each town\'s roofs carry its realm\'s colours, and the seat of a realm is a town with its own lord and garrison.',
      'Your save carries straight over. Your level, gear, gold, companions and everything you own are untouched. The first time an old world loads, it takes up the new realms once: a far province of each old kingdom breaks away (never a place you are warden of) and the far lands you have found gather into their realms.'
    ] },
    { v: '0.22.0', items: [
      'Slimes are the strongest monsters in the game. Whatever its level, a slime is one of the hardest things in the realm to kill. It has more life than a cave troll, hits harder, and shrugs off half of every blade and more of every arrow. It heals as you cut it, drinks your mana with every blow (and heals on it), spits acid, swallows what stands too close and splits when it dies. Even a slimeling, a piece of one, is a match for several goblins, and two pieces that meet crawl back together into a slime (twice; the third time it stays dead). Fire stops it healing for a while. It is slow and keeps to its own ground, so you can walk away.',
      'And they have the highest potential of anything: six forms instead of four (slime → ooze → great slime → slime king → slime emperor → primordial ooze), the first of them early, each a bigger step than any other kind takes.',
      'Slimes are the rarest monsters too. No dungeon or land keeps them as its own any more. Instead one turns up, very seldom, on any floor of any deep place (a few in a hundred) or out in the wild (about once in an hour or two of wandering), glowing green where it lies, with a banner when you first see it. Its target card warns you it is far stronger than its level.',
      'The reward is huge. Beat a rare slime for three times the experience (and a champion\'s share on top), its core, an epic or rare relic, fine gear, a heap of coin and gel, renown and a deed in the chronicle.',
      'Tame one and it is the strongest beast you can have. It grows half as fast again as any other, rises past your own level (to a quarter above it), heals as it fights and has six forms to grow through. While it is fed and out with you, its life runs into yours and you heal steadily.',
      'A tamed slime feeds on your mana for as long as you keep it: in full while it is out with you, a quarter while it rests at your den, and more as it grows and evolves (the HUD shows how fast). Unfed, it weakens, and after half a minute it slips back to your den.',
      'Your mana grows now, and keeps what it gains. You get two more mana for every level (an old save has all of it at once). Every point you spend, on spells, relics or a slime you feed, deepens your mana well, a level at a time (+6 mana each, and faster regaining). You can also meditate an hour by your campfire, take the arcanist\'s lessons in any market (+10 mana each, twelve in all) and drink the cores of slimes you beat (the rare ones\' the most). The deeper your mana, the faster it refills. Your character page (K) has a new card for your mana and how to grow it.',
      'Your save carries straight over: your mana only grows, nothing resets.'
    ] },
    { v: '0.21.0', items: [
      'Monsters evolve. Every kind has higher forms and takes them as it grows stronger: a goblin becomes a hobgoblin, a goblin chief, a goblin king; a skeleton a skeleton warrior, a death knight, a bone lord; a duskwolf a dire wolf, a shadowfang, the great wolf; a giant rat a rat brute, a plague rat, a rat king; a cultist a cult adept, a zealot, a dark prophet; and so for every kind (those without forms of their own grow greater, dread and elder).',
      'Each form is bigger, harder to kill and hits harder. It fights with something new (a charge, a slam, a bolt, its own kind called up round it), glows and throws off sparks in the colour of its form, carries better loot and is worth more experience to beat.',
      'What makes a monster evolve: its level (the stronger ones are born in their higher forms: a few at a threshold, nearly all of them well past it), growing in the middle of a fight, killing (one of the townsfolk, one of your beasts, another monster) and beating you. When it crosses the threshold in front of you it evolves where it stands: a pillar of light, a ring, ✦ EVOLVES ✦, and it comes back at you healed and in its new shape.',
      'The thresholds rise with how strong a kind is to begin with (a goblin first evolves at level 12, a hollow king at 24), and the bestiary (J) shows every kind\'s ladder of forms, naming the ones you have seen.',
      'The named ones evolve too: the Rising powers take their higher forms as they climb day by day (and the realm hears of it), and come at you in them.',
      'Your own tamed beasts evolve as they rise with you. A banner and a deed in the chronicle mark it, the Animals page shows each beast\'s form and the level of its next one, and a beast from an older save takes the form its level has already reached.',
      'Your save carries straight over. Evolution keeps nothing new but a stage number on the named monsters and your tamed beasts.'
    ] },
    { v: '0.20.0', items: [
      'The realm takes up arms. Every town of a kingdom (and of the Order) keeps a garrison, and the bigger the place the more soldiers it keeps: a village a handful, a town ten or so, a city more, a capital twenty-five or thirty, and more again in a time of war. Soldiers are real people of the town: recruited from the country round about when the garrison is short, fed and paid by the crown, retired to the fields in peacetime when there are too many, promoted, and killed in battle.',
      'Leaders and commanders you can find. Every garrison has a captain (its best soldier), and a sergeant for every six; every kingdom has a Marshal who leads its armies and a Champion, the best fighter in the realm. A capital is the seat of its king or queen; a town of size is held by a lord or a lady; a village by its reeve. Rulers, lords and the Marshal walk with two bodyguards.',
      'A fair world: the people of the realm grow with you. Soldiers drill every day and climb to about half your level and more, captains further, adventurers of the Guild further still, and a kingdom\'s Marshal and Champion come close to your level and can pass it. Rulers can fight too now.',
      'Walls and towers: the crown pays for a palisade round its capital and every town of size, and a watchtower over the gate (masons, a plea for timber, the walls going up). A town\'s strength in a battle counts its soldiers\' levels, its walls and towers, its captain and its arms.',
      'You see the garrison: soldiers stand in pairs at the gates, walk the palisade and drill in the yard in ranks (in the morning and the afternoon), and in peacetime columns of soldiers march the roads between a kingdom\'s towns on patrol. The people who matter are named with their level as you come near them, and soldiers when you are close.',
      'Walking into a town tells you whose it is: "City of Ashmere · Lady … · 14 soldiers, walled ★★★★". The notice board has a new Lord & garrison tab: the ruler, the lord, the captain, the Marshal and the Champion with their levels; the garrison, its ranks and levels against yours; walls, towers and defence stars; armies on the road; the strongest of the kingdom; and the battles fought. Your journal\'s Realm page sets every kingdom\'s armies side by side.',
      'War, reckoned by levels and command: the Marshal leads the host out of the capital, leaving a third of the garrison behind, and the towns nearby send levies to join it. A general picks a fight it can win and waits for a better day when the walls are too strong. Battles weigh every soldier\'s level, numbers, walls, towers and the command on both sides.',
      'Battles in front of you: when a host comes up to an enemy town while you are near, the march stops and the battle is fought for real. Horns sound, the townsfolk run indoors, the garrison turns out between the town and the host, and soldier meets soldier. Inside the walls you are a defender; knighted by the attacking crown you march with the host; outside the town nobody takes you for a side. Enemy soldiers you cut down in a battle are war, not murder. Throw the host back (or take the town with it) and the crown you fought for pays you and remembers it.',
      'Your save carries straight over: an old world musters its garrisons, names its officers and trains its fighters up the first time you load it. Your own level, gear and everything else are untouched.'
    ] },
    { v: '0.19.1', items: [
      'The more you fell and mine, the faster you get. Your swing quickens with every level of Woodcutting or Mining and with practice — every tree you have ever felled and every stone you have ever broken counts, and keeps counting (about 30% quicker after a hundred, 55% after a thousand, 80% after ten thousand) — and each level takes a share of the strokes off (a master needs fewer than half). A tree that takes a beginner about six seconds takes a practised hand under two.',
      'Rhythm: work one after another and you find a rhythm that quickens you up to 30% more (shown as you start each one); stop for a few seconds and it fades.',
      'Hold E and you keep going: when one comes down you set straight to the next one in reach, and if you walk on with E held, each tree or stone you come up against comes down in turn.',
      'At 10, 25, 50, 100, 250, 500 and 1,000 felled (or broken) you are told how much quicker you have become. Your page (K) shows it all: how many you have done, your swing speed, the strokes a tree or boulder takes you now against when you began, and when you will be quicker again.',
      'A long day at the axe or the pick no longer slows how fast the craft itself grows (only the experience it gives toward your own level tapers off after a few dozen in a day).'
    ] },
    { v: '0.19.0', items: [
      'You now give off an aura of your strength, and it grows as you do. A novice has a faint ring of light at their feet; by Fighter and Veteran motes rise off you; from Champion runes turn in the ring; a Hero is wrapped in a shell of flame; past level 20 waves of light roll out across the ground; and the strongest are a blaze, with sparks circling them.',
      'It takes the colour of your rank — gold for a Hero, blue for a Warden of the Deep, orange for the Eternal and so on — mixed with the light of your finest relic, and the best of what you wear (epic and legendary pieces) makes it stronger. It burns brighter in a fight, blazes up as you gather a heavy blow, flares when you rise a level, lights the ground round you at night and in the dark places — and goes dark when you crouch to sneak.',
      'It is not only for show: foes three or more levels beneath you that come inside it are cowed, and their blows land 15% softer (25% if they are ten levels beneath you); those six or more beneath you falter when they first feel it. Elites, lords and the great beasts are not cowed.',
      'Your character page (K) shows your aura: its strength, what it looks like now, and how far it reaches. Esc → Gameplay sets it to full, subtle or off.'
    ] },
    { v: '0.18.1', items: [
      'Your blows kill again. What you strike down dies — no more kneeling, no slow-down, no "last breath" count — and that is now the usual way (your world is switched over once, the next time you play).',
      'Taming is something you choose, and quick: beat the beast or monster you are fighting (the one you are locked on, or last struck) below a third of its life — a lord, an eighth — and press E. You hold it down for a moment and it is yours, every time. Only that one calls for E, and only while you fight it, so the prompt no longer pops up for every hurt beast on the field or jumps ahead of everything else E does.',
      'If you would rather nothing died by mistake, L still switches to taming: last breath (what you strike down kneels for 12 seconds — E tames it, a blow finishes it) or the leash (it kneels until you choose). The item bar says so while you are taming; on the usual way it shows nothing.',
      'A Beastbinder relic no longer stops your kills: in the usual way its chains hold a strong foe still and it takes a third more harm from you and your beasts while held; only when you are taming does it make the foe fall beaten instead of dying.'
    ] },
    { v: '0.18.0', items: [
      'Magical equipment is much stronger now, and you will feel it. Rarity counts for far more: a legendary relic is about three times as strong as a common one of the same level, and its power does more — more leaps for chain lightning, a wider and longer frost nova, a bigger barrier that bursts when it breaks, a blink that leaves a blast behind, a bloom that heals your companions too, more spectral blades, up to three falling stars. Relics you already carry are brought up to the new strength the first time you look at them.',
      'Every relic now gives a gift that is always on while you wear it, free: Stormcaller harder blows with blade and bow, Rimeheart less harm from every blow, Aegis more life, Wayfarer quicker feet, Lifebloom life that comes back even in a fight, Spectral mana that comes back faster, Beastbinder beasts and companions that bite harder, Starfall a deeper well of mana and more spell power.',
      'Relics wake by themselves when the moment comes, spending mana: lightning at the foe in front of you, a frost nova when they crowd you, a barrier when you are hurt or outnumbered, a blink out when you are near death with a foe on you, a healing bloom when you are low, spectral blades when they close in, a binding on a strong foe\'s wind-up, and stars where the foes are thickest. One at a time, the ones that keep you alive first, and the ones that strike keep a little mana back for your fire. Z, X and C still wake them by hand, and each can be set to by-hand-only.',
      'More slots: a fourth relic from level 12 and a fifth from level 30 (these two work by themselves).',
      'A new relics page (I): your slots as cards with each relic\'s power, what it does, its gift and whether it wakes by itself; everything you wear added up; your satchel sorted best first, each piece compared with the one you wear of its kind; and "Wear the best I carry". Over the item bar, a relic bar shows each one worn — its key, its rest counting down, the mana it needs, and a glow when it wakes.',
      'Dungeons drop relics: far more often from what you kill below ground, a strongbox sometimes holds one, and the chest at the bottom of every dungeon always does (rare or better). And the strong carry the best: elites fine or better, the lords of the deep places rare (epic from level 25), the beasts of the lairs and the lords of the deep woods epic or legendary, titans one or two epic or legendary, the sovereigns beyond the gates legendary. The arcanist still sells them, but never legendary.',
      'Fixed: opening a stone circle no longer takes off every relic you wear (if it did, the ones it can still read are put back on).'
    ] },
    { v: '0.17.0', items: [
      'The land can be changed by your own hand. Walk up to a tree and press E: you swing at it stroke after stroke (keep still — step away, or take a blow, and you leave off), it gives a creak, and it comes down in front of you, crashing through its own boughs. What is left is a stump, chips in the grass and a load or three of timber in your pack.',
      'Stone too: press E by a stone in the grass, a boulder on the hills, or the rock face of a mountain. Boulders break with anything you carry; the living rock of the mountains wants a pick — and what you cut away stays cut, so you can make your own way through a ridge, a tile at a time. Ore every time, and now and then a gold nugget, a garnet or a sapphire.',
      'Nothing grows back from stone, but the woods do: a stump sends up a sapling after a season, and in a season or two more it is a tree again where it stood — unless someone has built, paved or ploughed there since. Trees in the deep woods are older and slower to fell, and give more.',
      'A woodsman\'s axe and a miner\'s pick at every market (Tools of a peaceful trade) halve the strokes. Two new crafts grow by the work, with their own ranks and perks: Woodcutting (fewer strokes, more timber, burls of figured wood that carvers pay well for) and Mining (fewer blows, more ore, gold and gems twice as often, and living rock nearly as easy as a boulder). Both earn experience, like the other peaceful crafts.',
      'Timber and ore sell at every market — dearest where a town is building or short of iron — and a homestead is built of them.',
      'Fell enough in one place, or break enough stone, and the place takes your name: folk call it Vey\'s Clearing, or Vey\'s Quarry, or Vey\'s Cut if you went into the rock — and the Chronicle remembers who did it.',
      'You are not the only one at it: every town with a working lumber camp sends its woodcutters into the woods round it most days. Lumber camps are ringed with stumps and saplings now, and the woods come back about as fast as they are cut.',
      'All of it is kept with your world and nothing resets: a world from before this version simply starts changing from here on.'
    ] },
    { v: '0.16.0', items: [
      'A new look for the whole game, matching the map: every panel and tab — journal, notice boards, character sheet, shops, smithy, inn, archive, dialogue, choices, the pause menu, keys, the title screen — is now a glass console with cyan light at its edges, crisp new type (Inter for reading, Rajdhani for headings), glowing tabs, and amber for what you earn.',
      'The HUD matches: your name, level, life, stamina and mana sit on a glass plate with light-edged bars; the clock, the item bar, the foe you face, the boss bar, the big place-name banner and the messages down the right are all restyled; each kind of message has its own coloured edge.',
      'In the world: shop signs, name tags, speech and the [E] prompt are glass tags with a light edge instead of paper and brown boxes, and every label uses the new type. Below ground, the corner map is drawn in the same frame, with the floor you are on.',
      'The land is smoother: grass, woods, sand, hills and snow now shade gently into one another instead of showing every tile as a square of its own (paving, fields and ruins keep their clean edges). Shorelines and paths read as part of the ground.',
      'The Guild\'s page is full from the first day of a new world.'
    ] },
    { v: '0.15.0', items: [
      'Great events — rare, and the world is different after each. You hear of them wherever you are, and every notice board has a Great events page with what is happening and what you can do about it.',
      'The Great Migration: a great beast comes into a country, and everything that can run, runs — the wolf packs of every country round it, the herds, and the people of the villages near it, who take to the roads for safer towns. Out in the wild you see the herds go by.',
      'The Dungeon Bloom: the deep places of a whole region wake at once — some infested, some awakened, all deeper and worse — and the towns near them post rewards for anyone who goes down. Put down two or more and the realm will remember it.',
      'The Broken Crown: a crown passes and someone will not kneel. The kingdom splits town by town and there is war until one of them holds it all — battles on the border, towns going over, soldiers dying. Declare for a side and march to its battles: if it wins, gold, influence and perhaps a knighthood; if it loses, you are wanted.',
      'The Sleeping God (once in a world): everyone dreams the same dream, of something vast asleep under a deep place. The ground shakes, people walk out of their towns at night to go down and sing to it — you will find them there — and if no one reaches the bottom and sings it back to sleep, it turns over: the earth opens, every dungeon for a hundred leagues wakes, and something walks out of the ground. (The Guild\'s best may try, too.)',
      'Towns have characters now, made from who lives there and what happens to them: farming towns, mining towns, market towns, garrison towns, walled towns, holy towns, adventurers\' towns, thriving towns and towns in decline. Each does something (farm towns fill their granaries, walled and garrison towns hold better against raids, thriving towns draw families from declining ones), changes slowly, and the Chronicle says so when it does. See it on the map and under Town affairs on the notice board.'
    ] },
    { v: '0.14.0', items: [
      'The Adventurers\' Guild. Forty or so real people of the realm — guards who wanted more, hunters, wanderers, a hedge-mage or two — live by the same trade as you, each with a rank from E to S, a way of fighting and a temper (reckless, careful, greedy, honourable, glory-hungry). Every day some of them take contracts off the notice boards and go down into the dungeons in parties.',
      'They take the same pleas you do, and whoever finishes first is paid: take a job and dawdle, and a glory-hungry B-rank may beat you to it (you are told when one takes your job, and when they finish it). Or they fail — and leave the wolves half dead or the beast wounded, so it is easier for you.',
      'They grow famous and earn names (Wolfsbane, the Deepdelver, the Unbroken, the Bold…). They die, and their gear lies where they fell, marked on your map: find the body, take what is useful, and bury them if you will. The old and the rich retire and open an inn or a smithy. When one dies or leaves, someone new signs the book. See them all on any notice board, under The Guild, or from your character sheet (K). Talk to one and they tell you their rank and what they make of you.',
      'Your name is now seven things, not one: Heroism, Honour, Fear, Reliability, Influence, Knowledge and Infamy, grown by what you do (help people, keep your promises, find things out, rule land — or be cruel, break your word, break the law). The Crown, the common folk, the Guild, the Wardens and the underworld each read them their own way. What the common folk think changes shop prices; a feared name makes outlaws who face you lose their nerve sooner.',
      'And stories about you go round — some grown in the telling, some made up out of nothing, flattering or ugly. Let them stand, or set the record straight (and be known for honesty). Ask anyone "What do people say about me?" Everything is on your character sheet (K) → Your name.',
      'Your progress carries over: on an old save the Guild fills its book from the people already living in your world, and your name starts from what you have already done.'
    ] },
    { v: '0.13.0', items: [
      'Beasts migrate. When a great beast settles into their country, a monster\'s lair hunts them, the hares run out or hunters kill them too fast, a country\'s duskwolves leave it — the whole pack, over a few days, toward the neighbouring country with the most to eat. Where they arrive they are hungry and do not know the land: they take the villages\' sheep, the villages ask for help on their notice boards, and the Chronicle tells it.',
      'Their tracks cross the land between, dozens of prints all going one way. Study them (E) and you learn what drove them out — and can mark it on your map and follow them back to it.',
      'The chain goes on: kill off a country\'s wolves and its hares multiply past counting, and a country so full of prey draws a great beast out of its own range to feed on it.',
      'Wolves no longer die out across the world: the woods feed them (deer, boar and carrion besides the hares), and great beasts mostly drive them off instead of eating them. In a world where they had died out, packs come back over the next weeks.',
      'Every dungeon has a history — an underground kingdom, a prison for something that could not be killed, a mage\'s vaults blown apart by an experiment, a mine that broke into what was buried, a warren grown by a thing that eats magic, a temple that opens under the stars, a battlefield where the dead still fight. Each floor shows you one sign of it; read them all and the map\'s card tells you the whole story.',
      'And a state that changes day by day: Dormant, Active, Infested (its creatures spill out into the country round it and trouble the villages near it), Contested (a second brood moves in and the two fight each other as readily as you), Worked (adventurers camp at its mouth and the town nearby grows rich on it), Awakened (new depths open and everything in it is stronger) and Collapsed (some ways sealed, and the fall opens others; it is laid out anew). Its state shows on the label over its door and on the map, with what happened there lately.',
      'Dungeons remember you. Fight hard in one and run, and they are waiting for you inside the door next time. Kill what ruled it, and when it fills again its creatures may come back as two warring bands. Empty it, and something new may move in instead of what was there. Come back and you are told what changed while you were away.'
    ] },
    { v: '0.12.3', items: [
      'You can take a mark away now. Before, clearing a waypoint only went back to pointing at your road\'s next step, so a marker stayed. Now clearing means nothing is marked at all, until you choose somewhere again.',
      'Ways to clear it: on the map (M), the side panel always shows where you are Headed to, with ✕ Clear; click the marker on the map and its card has ✕ Remove waypoint; right-click your waypoint again to take it away; or N · where to? → ✕ Clear — no destination.'
    ] },
    { v: '0.12.2', items: [
      'The guide at the top of the screen and the trail on the ground are gone, for a clearer view. The minimap still draws your way in light and marks where you are headed, and an arrow at the edge of the screen (kept clear of the panels) points to it with how far. Want either back? N · where to? has a switch for each.'
    ] },
    { v: '0.12.1', items: [
      'The guide at the top of the screen is simpler to follow: instead of a heading tape that slid with the way you faced (which jumps about as you fight, aim and walk), a dial with a gold needle points on the screen the way to go. The view never turns, so the needle up is W, up and to the right is W and D, and so on; north is marked on the dial (at the bottom when the view is turned over a pole). Beside it: how far, to where, and the way.'
    ] },
    { v: '0.12.0', items: [
      'The minimap is now a nav-scope: a round radar of the land about you with a bezel marked in degrees (north in gold), range rings, a sweep going round, the way ahead drawn in light, what hunts you as red blips, the way you face as a cone of light, and where you are headed as a gold diamond — or, when it lies beyond, a mark on the rim with how far. Under it: your heading in degrees and where on the world you stand. Scroll on it to range in or out; click it for the full map.',
      'The guide at the top of the screen is a heading tape that slides as you turn, every five degrees marked: where you are headed is a gold diamond on it — bring the middle onto the diamond and it says On course, otherwise which way to turn and how far. Under it: the distance in leagues, the place, and the way (follow the road north, through the woods…).',
      'In the world, the trail on the ground is a line of chevrons of light with a pulse running out ahead of you (pointing the right way on the screen, over the poles too); where you are headed has a reticle of light over it with its name and distance, and when it is off the screen an arrow at the edge points the way, with how far.'
    ] },
    { v: '0.11.0', items: [
      'The map (M) is now a navigation console: the globe glows, with lines of latitude and longitude in light, a bright rim, a slow sweep going round it and rings in orbit with their satellites (all fading away as you come down close), and round the view a compass that turns with the world, an altitude ruler you can drag to come down or go up, a scale, and a readout of where the pointer is.',
      'Easier to use: search right on the globe (press / and type, Enter flies there); big buttons for Me, Goal, World and Chart; W A S D or the arrows turn the world and Q / E zoom; Space finds you, G flies to where you are headed, H shows the whole world, T switches to the flat chart; double-click flies in; right-click anywhere sets a waypoint and guides you to it; let go mid-drag and the world spins on.',
      'The way to your goal is drawn on the globe as a line of light (along the planned road, or the short way over the world), with a beacon over the place; when it, or you, is out of sight an arrow at the edge points the way (click it to fly there).',
      'The side panel: a card for the place you chose (Guide me there, Fly to), the map layers as switches, and a list of what is Nearby (nearest first), the Dungeons you know, or the Key. The side panel can be folded away for a bigger globe, and ? shows the controls.'
    ] },
    { v: '0.10.13', items: [
      'Riding a horse over a pole works: before, the horse kept galloping the old way after you crossed, which threw you straight back over the pole, and back again, every frame — the view flickering, you spinning on its back, the horse facing every which way. Now the horse (and your own feet, a roll, a lunge, a slide on the ice, a boat you are rowing) turns with you over the top and carries straight on down the far side.',
      'Creatures carried over a pole with you turn every way they were heading and every push they were under, so a charge or a knock-back goes on the way it was going.'
    ] },
    { v: '0.10.12', items: [
      'Nothing appears or disappears any more as you cross the edge of the world (the east-west join or a pole). Everything drawn — camps, ruins, towns, hidden places, the plants you gather, birds, footprints, lights, lamps, beacons — is now shown at its place nearest you, round the world or past the pole (turned about, like the land), so what you see the moment before you cross is what you see the moment after.',
      'Over a pole, everything round you comes with you, not just your own animals: other creatures, what lies on the ground, arrows and spells in the air.',
      'The sun and moon turn with the view over a pole, so shadows and sunlit sides no longer flip round as you cross.',
      'The way to your goal is planned the short way across the east-west join (the trail, the minimap line and the leagues stay right as you cross), and the minimap shows camps, lairs and towns over the join and past a pole.',
      'Water past a pole is drawn on the very same surface you find when you get there.'
    ] },
    { v: '0.10.11', items: [
      'No more glitch going over a pole: your dragon (and you, your horse and your beasts) no longer spin round the moment you cross. The view turns with you over the top, and now the way they are drawn turns with it at once, so they fly or walk straight on.',
      'The land just past a pole is settled before you get there, not the moment you arrive: lakes, shores and places over the top are already there as you come up to them, instead of appearing all at once as you cross.',
      'Water past a pole is drawn as it really is (frozen or open, deep or shallow), so it looks the same before and after you cross.'
    ] },
    { v: '0.10.10', items: [
      'Walking up to a pole is now seamless: the land beyond the pole no longer slides about as you walk along it. The line you cross over is fixed as you come near, so the far side holds still, and when you go over it the ground under your feet is the ground you saw.',
      'The snowfields round the poles are no longer walled in by boulders: the polar ice is clear, and the snow elsewhere on the globe has far fewer rocks, so you can always walk on through.'
    ] },
    { v: '0.10.9', items: [
      'Going over a pole is now seamless: the land past the pole (the far side of the world, turned about, as it really lies) is drawn as you come up to it, and as you cross the two simply change places — the view the moment after is the view the moment before, with nothing rebuilt and no sudden switch. The weather and the land\'s name stay the same over the top.',
      'Your dragon no longer flickers when flying fast or over the world\'s edges: the beast you ride is drawn exactly under you every frame, and fast-moving creatures ease smoothly instead of jumping one frame and lagging the next.',
      'When new country is settled near you, only the ground that changed is rebuilt, not everything in sight — less stutter while exploring.'
    ] },
    { v: '0.10.8', items: [
      'No more freeze when you fly (or walk, or sail) round the world: crossing the east-west join or a pole used to stop and start the whole game again, and settle all the country round where you came down. Now you are simply carried over — your dragon, your beasts and the land already in sight come with you — in a fraction of a frame.',
      'In the sky the currents of the rivers below are left alone, one less thing for the game to work out as you fly.'
    ] },
    { v: '0.10.7', items: [
      'Much less lag and freezing in the world. New country is now made one stretch at a time and only on the ground (not while you fly over it), and making it no longer scans the whole globe: the deep woods, the rivers\' currents and the sea\'s depth are worked out only where the land changed.',
      'Midnight no longer stops the game: a day\'s work for the whole world is spread over the next few frames. Merchants trade with the towns within reach and pilgrims go to the nearest temple, instead of walking half round the world, so the world runs lighter and saves smaller.'
    ] },
    { v: '0.10.6', items: [
      'The globe map no longer lags when you zoom or turn it: finding the place under the pointer is now worked out directly instead of searched for, the map draws at most once a frame, and the sharper painting of the land waits until you stop moving (and paints faster when it does).'
    ] },
    { v: '0.10.5', items: [
      'Walk all the way round the world, like Earth: going over a pole no longer turns you back or stops you — you walk straight on down the far side, and the view turns with you so what was ahead stays ahead (the little map turns too). On a dragon the same.',
      'No more sea at the world\'s join: the land runs on east and west all the way round with no seam, so you can walk 360° without a boat.'
    ] },
    { v: '0.10.4', items: [
      'Flying over a pole on your dragon now carries you on down the far side of the world instead of holding you against the top of it like a wall.',
      'The globe map is sharp at every distance: the part you are looking at is painted again, piece by piece, as finely as you are zoomed (tile by tile close in, with trees, roads and rivers).',
      'Lands on the globe are no longer drawn stretched: from the equator to the middle latitudes every tile is square on the globe, and only the far north and south are drawn out toward the poles.'
    ] },
    { v: '0.10.3', items: [
      'Zooming in on the globe map now leans the view forward, so the curved edge of the world and the sky above it stay in sight however close you come: it never flattens into a flat chart.',
      'Lands you have not walked show through on the globe (paler) even when the map is set to show only what you have walked, so the whole globe is always covered.',
      'The game\'s version is shown in the corner of the globe map.'
    ] },
    { v: '0.10.2', items: [
      'The whole globe is land and sea now, drawn from the start: continents, lakes, ice caps and the World-Sea are all there to see on the map, not just the lands you have reached. Villages, people and dungeons still appear as you travel to them.',
      'The globe map stays a globe however close you zoom, and close in it paints the ground beneath you sharply: trees, roads and rivers. (🌐 still switches to the flat chart if you want it.)'
    ] },
    { v: '0.10.1', items: [
      'New country is now made around you while you keep playing, a little at a time, instead of the game reloading: no more pause on the edge of new land.',
      'Over the poles: hold your direction and you carry straight on down the far side of the world, instead of turning back.',
      'The guiding arrow and distances take the short way round the world.',
      'The globe map shows day and night: the sun stands where it is noon, further north in Bloom and south in Frost.'
    ] },
    { v: '0.10.0', items: [
      'The world is round: every world is now a globe (2,880 tiles around, 1,440 pole to pole) with no edge. Go far enough east and you come back from the west; walk over the pole and you come down the far side. New country is made as you travel toward it, with its own regions, villages, people, beasts and dungeons. The poles are ice you can walk on, and the World-Sea on the far side has two strands of sand across it. Your save moves onto the globe and keeps everything.',
      'The map (M) is a 3D globe you can turn and zoom: known lands painted on it, the rest uncharted. Click places as before; the pointer shows latitude and longitude. 🌐 (or scrolling all the way in) opens the flat chart.'
    ] },
    { v: '0.9.7', items: [
      'Living dungeons: Mawtide and Grimmaw sleep with their jaws open — creep up at night and climb down inside, into living chambers that clench, spit acid and breed parasites. Kill what lives at the heart and the beast itself is left weak.',
      'Ironback, the Walking Keep: a new great beast, a huge placid stag carrying a ruined fortress on its back. Climb its flank into the keep and fight the dead garrison while the whole place lurches with each step. You come out wherever it has walked to.'
    ] },
    { v: '0.9.6', items: [
      'Lure a calamity: strike a dragon or great beast and it follows you a long way. Lead it into a bandit camp, an Ashfang town, or another titan\'s range, and it turns on them instead — it falls on the camp, or the two beasts fight it out while you watch. The loser flees to new ground, or dies.'
    ] },
    { v: '0.9.5', items: [
      'The great lands: every region now belongs to one — the Emerald Expanse, the Ashen Wastes, the Frozen Crown, the Forgotten Kingdom, the Blighted Lands, the Celestial Highlands (with islands of rock floating over the hills), the Abyssal Depths, or the safe Heartlands — worked out from the ground itself, so your world has them too.',
      'Each land has beasts of its own abroad: fire hounds and slag golems in the Ashen Wastes, frost hounds in the Frozen Crown, the risen dead of the Forgotten Kingdom, rot hounds in the Blighted Lands, storm wisps over the Celestial Highlands, things from below at night in the Abyssal Depths. Never close to a town.',
      'You are told when you cross into a new land; its name shows by the clock and on the world map. The hard lands train your Wayfarer twice as fast.'
    ] },
    { v: '0.9.4', items: [
      'Lore of the wild, on your character page (K): skills learned only by doing — Hunter (hunt beasts and monsters; from rank 2 the foes near you show on your minimap), Beast-lore (study them with F), Delver (clear dungeon floors), Calamity-hunter (wound dragons and great beasts) and Wayfarer (travel in storm, snow, rain, fog and heat). Five ranks each, each rank a real edge.',
      'Dungeons that nobody clears grow, day by day: deeper, with stronger things in them — and after a month, things come out of them at night. Clear one and it starts again. You are told how long one has stood untended when you come on it.',
      'Fixed: a house in another town than the one its owner died in now passes to the heir too.'
    ] },
    { v: '0.9.3', items: [
      'Healing arts, on your character page (K): Renewal, Victor\'s breath, Lifesteal (level 5), Second wind (level 10) and Mending pulse (level 15, heals your beasts too). Switch up to three on — in a fight they heal you by themselves, no key pressed — and switch them in and out whenever you like. Renewal and Victor\'s breath start switched on.'
    ] },
    { v: '0.9.2', items: [
      'A beast you do not want is yours to kill: when one kneels (on its last breath, beaten on the leash, or a lord brought down), press E to tame it — or simply strike it again and it dies. Before, a kneeling beast on the leash or a beaten lord could not be touched.',
      'On "to the kill" (L), lords no longer kneel either: everything you strike down dies.'
    ] },
    { v: '0.9.1', items: [
      'The journal (Tab or J) now holds just your beasts: Tamed beasts and Animals. Want every page back (guide, story, people, letters…)? Esc → Gameplay → Journal → Every page.'
    ] },
    { v: '0.9.0', items: [
      'Calamities walk the world. Every dragon and great beast now has a class — I Lesser, II Greater, III Catastrophic, IV Extinction, V Primordial (that one sleeps) — and none of them waits for you in an arena: hunger or restlessness sends them off across the country to new ground, in the world\'s own time.',
      'When one passes near you, the birds go quiet and the ground shakes, and you are told where it is going. Follow it, fight it, or keep out of its way — crouch (Ctrl) and it may pass you by. The great ones ignore you unless you come right under them or strike them.',
      'A town in its path sees it coming in stages: travellers\' tales, then shut gates, dear bread and a call for help, then the beast itself — and what it costs depends on its class. Slay or bind it first and the town pays you and remembers it.',
      'Two calamities that meet will fight. Where one dies, a new dungeon opens some days later — the Scar of …, full of things of its kind.',
      'The world map shows every titan where it is now, its class, and where it is heading.'
    ] },
    { v: '0.8.41', items: [
      'Your beasts grow by fighting: the one that lands a kill learns most, the rest of the pack nearby learn by watching, and they learn from your kills too.',
      'A beast grows up to your level (or the level it was tamed at, if higher). At that height its skills grow instead — mastery ★1 to ★30: each rank hits harder (+3%), lasts longer (+2% life) and brings its arts back sooner, and it learns new skills on the way: Thick hide (★5, takes less harm), Killer instinct (★10, more harm to the wounded), Second wind (★15, heals once when hard pressed), Swift arts (★20) and Apex (★30).',
      'The Tamed beasts page shows each beast\'s growth or mastery, the skills it has learned and the next one; the long how-to folds away.'
    ] },
    { v: '0.8.40', items: [
      'No more than two of any one kind of beast: once two goblins (say) are yours, a third goblin cannot be tamed — it fights and falls like any other, with a small note "you have two goblins". Lords and the great beasts of lairs are each one of a kind and never count. Any you already keep stay yours; release one (U) to make room for another.'
    ] },
    { v: '0.8.39', items: [
      'The beasts you call with Y — your bound dragons and great beasts, and your horse — now appear at the top of the Tamed beasts page (U), with their pictures, life, where they are, and Call / Send away buttons. The Animals page shows their pictures too, and the tab counts them.'
    ] },
    { v: '0.8.38', items: [
      'The smithy shows how each blade or bow compares to the one you carry: ▲ +6 in green, ▼ −4 in red, or "= yours".'
    ] },
    { v: '0.8.37', items: [
      'The land breathes: grass, crops, reeds, bushes and the crowns of trees sway in the wind, each in its own rhythm, in gusts that roll across the country, and harder when rain or a storm comes on.'
    ] },
    { v: '0.8.36', items: [
      'Sturdier: each part of a frame (the world, the drawing, the menus, the music) now stands on its own, so a fault in one can never freeze the others; it is reported once, in plain words, and the game carries on.'
    ] },
    { v: '0.8.35', items: [
      'Conversations are numbered: press 1–9 to pick an answer (0 for the farewell at the end of a long list).',
      'A heap of dropped gear is taken up whole: E on it says "Take all (3)", and one note lists what you got.'
    ] },
    { v: '0.8.34', items: [
      'Your pack wears a green ring at its feet, so in a crowded fight you can tell your beasts from the wild ones at a glance.',
      'Levelling up raises a column of light where you stand, with a ring rolling out across the ground; a new rank raises a taller one in its colour. A beast you tame goes up in a green column as it joins you.',
      'The title screen centres your worlds.'
    ] },
    { v: '0.8.33', items: [
      'Play every menu with a controller: in the pause menu, the journal, the shops, a conversation or the title screen, the D-pad or left stick moves a gold frame from button to button, A chooses, B goes back, LB / RB turn the journal\'s pages and the right stick scrolls. The mouse works exactly as before.',
      'A foe that grows suspicious shows a big yellow "?" over its head, and a red "!" when it spots you, instead of a little speech bubble.'
    ] },
    { v: '0.8.32', items: [
      'The worlds beyond the gates have living pools: lava crawls with bright veins and a cooled crust at its edges, the abyss glimmers cold, the thorn-world ooze slowly churns.',
      'Old worlds stay lean: people long dead keep their names, kin and strongest memories, but no longer carry every grudge and errand into the save. A world played for years saves smaller and faster. Nothing you know about anyone is lost.'
    ] },
    { v: '0.8.31', items: [
      'Surf: a white lip of foam where water meets the shore, and thin lines of it rolling in over the shallows.',
      'A small "World kept" note shows in the corner whenever the game saves (every minute, each new day, and when you leave) — and says so plainly if your browser refused to save.',
      'In the woods you are no longer washed pale blue-white: the trees open up around you instead.',
      'The journal always lights the page you are on.'
    ] },
    { v: '0.8.30', items: [
      'Choose your challenge: Esc → Gameplay → Story (foes hit half as hard and fall sooner), Balanced, or Hard. Change it whenever you like; your world and progress are untouched.',
      'Spoils lying in a heap are one tidy list over it — the best thing first, the rest summed up ("and 3 more") — instead of labels written over each other.',
      'The settings you have chosen are lit in gold, so they no longer look greyed out; the menu is wider, so each choice sits on one line.',
      'The see-through circle around you is a little wider, for thick woods.'
    ] },
    { v: '0.8.29', items: [
      'Never lost behind the scenery: a boulder, a tree crown or the corner of a house that stands between you and the camera now fades away in a soft circle around you (its shadow stays). Turn it off in Esc → Gameplay if you prefer.',
      'Underground you carry a little light of your own, so you and your pack are never black shapes in a dark tunnel.',
      'Cave and crypt floors are rough rock and worn flagstones now, not a chequered pattern; house floors lost their stripes too.',
      'Entering a cave or crypt clears its "E to enter" note.'
    ] },
    { v: '0.8.28', items: ['Set your own keys: menu (Esc) → Keys… lists every action with its key — click Change and press the key you want (if another action has it, the two swap), or reset them all. The controls card (F1) shows your keys.'] },
    { v: '0.8.27', items: [
      'New Gameplay settings in the menu (Esc): pause when you switch away from the game (on by default — click elsewhere and the world waits), screen shake (full, gentle or off), damage numbers (on or off), name tags in a fight (the nearest, or all), and the size of the interface (smaller, normal, larger, largest).',
      'In long sessions, coin and parts left lying far behind you are let go, so they no longer pile up (dropped gear stays in the world and is found again when you come back).',
      'More of the game is checked automatically each build: tamed beasts\' sizes and the places they fit, the ways of taming, who your pack may fall on, relic strength, the limit to grown mana, and draught prices.'
    ] },
    { v: '0.8.26', items: [
      'Smoother big fights: a crowd of monsters with your pack used to spend most of each frame working out routes it could not take; the same fight now runs about six times lighter, and towns and the deep woods are lighter too.',
      'Clearer fights: your tamed beasts are named only when you look at one or it is hurt (with a small health bar), only the five nearest foes are labelled in a crowd (and whatever you look at or lock on to), your pack no longer shouts "a roar", and the strip of key hints at the foot of the screen steps aside once you reach level 5 (F1 still shows every key). The relics on the HUD are named in words.',
      'Controls: C no longer makes you sneak (it wakes your third relic; Ctrl sneaks, and lowers your dragon). On a controller, hold LB and press X, Y or B to wake your relics, or A to call your pack; tap LB alone to lock on.',
      'Balance: relics grow with your strength as your blade does, so one of your level stays worth carrying all the way up; the Aegis barrier is at most nine-tenths of your life; the mana you grow by use is deep but not bottomless (up to +300). A beaten beast rests 45 real seconds whatever the pace of the world.',
      'Sturdier: a building with no inside can no longer be entered by mistake; tested end to end — towns, every page, taming, fights, relics, potions, every kind of dungeon, a gate\'s world, dragon flight, days passing, saving and loading — with no errors.'
    ] },
    { v: '0.8.25', items: [
      'Fight from the sky. On your dragon\'s back: hold the left mouse button and it breathes its element in a line along the ground toward your mark; the right button rains it down round the mark; Q sends it diving on the mark — it swoops down, slams the ground and climbs again; F looses its own great art (a wall of fire, a blizzard, chain lightning, a sunbeam… by its kind). Lock on (R) to a foe and all of it goes there. Your relics (Z, X, C) work up there too. The foot of the screen shows what is ready.',
      'Fixed: your own dragon\'s attacks no longer strike your tamed beasts.'
    ] },
    { v: '0.8.24', items: ['Monsters, beasts and your tamed pack no longer pass through one another. Each takes up as much room as it is drawn (a great ogre is as wide as it looks), walks round the others instead of into them, is stopped by the bodies behind it when it is thrown back or charges, and the bigger shoulders the smaller aside. Bodies that end up on top of one another are pushed apart at once.'] },
    { v: '0.8.23', items: ['Fixed: while you flew on your dragon, your tamed beasts below kept vanishing and reappearing — they could not keep up, and were snatched back to you over and over. Now, while you are in the air, they follow out of sight, and the moment you land they are at your side ("your beasts catch up").'] },
    { v: '0.8.22', items: [
      'Size matters below ground. Every tamed beast is small, large or huge: small is anything up to a cave troll\'s build; large are ogres, golems, the great hounds and the like; huge are the great beasts of the lairs, the widows and wyrms of the deep woods. Caves, hideouts and grots let only the small in; dungeons, crypts and mines keep out the huge; the worlds beyond the gates take any.',
      'Beasts too big for a place wait at the way in (you are told who), and are with you again when you come out. Press O inside and smaller ones from your den come in their place. The Tamed beasts page shows each one\'s size, and which are too big for where you are.'
    ] },
    { v: '0.8.21', items: [
      'Dragons fly much faster: cruising 22 (was 14), Shift 42 (was 27) — and hold Shift a moment longer and your dragon finds the wind and rides it at 52. They gather speed twice as quickly, climb and dive more readily, and leave the ground in a second (was over two).',
      'Landing is quick: your dragon flies straight at the nearest clearing, drops hard and true and flares at the last moment — about two seconds from cruising height (was six). Press V again while it comes in to drop straight down at once.'
    ] },
    { v: '0.8.20', items: [
      'Your tamed beasts no longer fall on townsfolk, the watch or the realm\'s soldiers. They had been killing anyone who turned on you — and every such death was laid at your door as murder, until the towns would not trade with you. Now they fight only outlaws, beasts and monsters, and those who came at you first.',
      'A market, smithy or inn that will not deal with you now shows your standing in the town, and lets you make amends with a gift of crowns — after which they trade with you again.',
      'The market cannot be shut whole by one stall: if any part of it fails to draw, the rest opens, and whatever went wrong is shown on screen (anywhere in the game) so it can be reported.'
    ] },
    { v: '0.8.19', items: [
      'Your tamed beasts no longer stand about in a fight. They know everything that has struck you or them (archers and casters far off too), everything that means you harm near you, and they think again the moment you are hit.',
      'Anything shooting at you from afar is hunted down by the quickest beast ("hunts the shooter"); anything that attacks one of your beasts is answered by it; anything else at your throat is met ("guards you"); your mark (R) is answered at once ("on your mark").',
      'When you are badly hurt, the beast covering you goes for whatever is nearest you instead of standing at your side — and when nothing is near you it fights with the rest.',
      'A beast only gives up on a foe it truly cannot reach (it is stuck, not merely chasing), and then finds a way round or turns to the next; when its foe falls it goes straight to the next. They step out of the ground about to break under them and the breath about to come, and no longer shy away from your own heavy blows.'
    ] },
    { v: '0.8.18', items: [
      'Your tamed beasts fight as one pack, with a mind for the fight. They fall on what you are fighting — the one you are locked on to (R), else what you last struck, else what is coming at you hardest — and spread round it, the far side first: a blow from behind lands harder, and on anything staggered they all strike harder still. An amber ring marks what the pack is on.',
      'They look after you: anything else at your throat is met by the nearest free beast; a blow wound up against you is broken by the nearest beast that can reach it ("interrupted!"); when you are badly hurt the toughest stands at your side and takes a third of every blow meant for you; a beast near the end of its strength falls back behind you to recover while the others hold the line. What they cannot reach, they leave for what they can.',
      'Each uses everything it has: wolves and hounds charge and howl (the whole pack strikes harder for a while), spiders poison and web foes in place, drakes breathe fire, wraiths blink behind their prey and drink from it, shamans heal the pack and you, slammers and lords throw back everything round them — and every beast has a power strike and a roar.',
      'They are stronger: they keep up with you (85% of your level, lords and great beasts your level) and hit a third harder for you than they did wild.',
      'What your beasts strike down dies; only your own blows leave a beast on its last breath (with the leash on, theirs spare it too).'
    ] },
    { v: '0.8.17', items: ['Fixed: the character page (K) would not open, with an error, if you carried an Arcane weapon or Manaweave armour — their pictures had no colour for the new magic. They glow blue and violet now.'] },
    { v: '0.8.16', items: [
      'Fixed: beasts that were beaten went home to rest but still held their place at your side, so you could not call the others. A resting beast no longer holds a place — and your save is fixed as it loads.',
      'O calls your pack: your strongest rested beasts come to your side at once, filling the empty places and trading up for weaker ones. Up to five can be with you now (was three).',
      'Call works on any beast in your den at any time: if your side is full, the weakest with you goes home for it. Send all to the den with one button.',
      'When one of yours is beaten it rests about 45 seconds (not until the next day), and the strongest rested one in the den comes to take its place.',
      'The den on the Tamed beasts page is a compact list, strongest first, each with its picture and a Call button.'
    ] },
    { v: '0.8.15', items: [
      'A page of its own for your tamed beasts (U, or Journal → Tamed beasts): each one on a card with its picture, drawn from its own body — wolf, goblin, spider, skeleton, golem, drake and the rest — with its level, what it was, its life, how near it is to its next level, its strength, its kills, and where it is. Those with you are shown first, then the ones in your den.',
      'From the cards: call a beast to your side, send it to the den, rename it, or release it (it asks first).'
    ] },
    { v: '0.8.14', items: [
      'Tame from a distance: no need to go near. Beat something down with arrows, fire, relics or your blade, and press E from where you stand — up to about eighteen paces, anything you can see. A golden ring marks the one E will tame; with several beaten at once, E takes the one you are locked on to (R), else the one nearest your cursor.'
    ] },
    { v: '0.8.13', items: [
      'Taming made simple: knock it down, it kneels, press E — it is yours. Taming never fails any more, takes under a second (a lord a little longer), works from four or five paces away, and is not broken by blows. When a beaten beast is near, E always means "tame it" first.',
      'A beast or monster you strike down now kneels for 12 seconds (was 8) before it dies. Anything worn below a third of its life can be tamed with E too, even while it still fights.',
      'You can keep up to 30 tamed beasts (was 12); three follow you at a time.'
    ] },
    { v: '0.8.12', items: [
      'No more taming chances lost to one hard blow. Now, by default, any beast or monster you strike down is left on its last breath: it kneels for 8 seconds with a warning and a countdown over it, slow-motion for a moment as it falls. Tame it (E) in that time, or strike it again to finish it; if the time runs out, it dies. Nothing you do hurts it in the first moment it falls, and the countdown stops while you hold it to tame.',
      'L now changes between three ways: last breath (the default), the leash (everything you strike down kneels for 25 seconds and gets up again — nothing kills it but Finish) and to the kill (it dies at once, as before). The bottom of the screen shows the leash or to-the-kill when they are on.'
    ] },
    { v: '0.8.11', items: [
      'Magical equipment: relics worn three at a time and woken with Z, X and C, each spending mana and resting a few seconds after — the Stormcaller (chain lightning), Rimeheart (frost nova that freezes), Aegis (a barrier that takes the harm meant for you), Wayfarer (blink six paces), Lifebloom (heals more than a third of your life and washes off fire and poison), Spectral (three blades circle and cut), Beastbinder (holds a beast still; for twenty seconds it cannot die by your hand and is easier to tame) and Starfall (a star falls where you aim). Find them on what you kill — more often on the strong — or buy them from the arcanist at any market. Wear them from your character page (K).',
      'Weapons can now be Arcane (each blow draws 3 mana and strikes 40% harder) and armour Manaweave (a third of the harm that reaches you is paid in mana).',
      'Your mana grows with use: every point you spend, and every moment you stand in a fight, deepen the well — your capacity and how fast it refills. The character page shows how far it has grown.',
      'Taming without killing: press L for the leash. While it is on, any beast or monster you or yours strike down falls beaten and kneels instead of dying, however hard the blow. Nothing kneeling can be hurt by your blows or your beasts; only Finish (E) ends it.'
    ] },
    { v: '0.8.10', items: [
      'Healing draughts in three strengths: the minor draught (cheap — a quarter of your life), the healing draught, and the greater draught that closes every wound. 1 drinks the one that best fits your wounds, and does nothing if you are not hurt.',
      'Six new draughts with their own keys: the mending tonic (5) heals slowly but deeply; the purging tincture (6) burns out poison, fire, fever and snares and keeps venom off for half a minute; the second-wind cordial (7) refills your stamina and doubles its return; the heartroot elixir (8) gives fifty more life for three minutes; bloodwine (9) heals you with every blow you land; phoenix tears (0) heal you fully and make you untouchable for five seconds — and if you carry one when a blow would bring you down, it breaks of itself and lifts you up.',
      'Every draught has its own makings and cost at the apothecary, and all but phoenix tears can now be bought ready-made for crowns alone, at a higher price. The draughts you already carry are kept.'
    ] },
    { v: '0.8.9', items: ['Your tamed beasts go down into the dungeons with you and come out with you, without leaving a copy of themselves waiting at the door.'] },
    { v: '0.8.8', items: ['The deep woods are far bigger — two to three times the land they covered, reaching up to thirty leagues from their hearts on a large map — with room for their fringe, their deep and their heart. Your existing deep woods grow to the new size the first time you load.', 'Tame anything. Beat a beast or a monster down to a third of its life and a "Tame" choice appears beside it (E), with your chance: hold it while you break its will (a moment for a beast, longer for a lord). The weaker it is, and the more you have tamed before, the likelier it gives in; if it does not, it tears free and fights on. Every monster of the dungeons, the deep woods and the gates can be tamed, wolves and the great beasts of the lairs too, and the named monsters of the Rising powers.', 'Lords and bosses no longer die outright when you beat them: they fall, beaten, and kneel for half a minute while you choose — Tame or Finish. A dungeon\'s lord tamed counts as beaten (its floor is cleared, its story goes on). The dragons and great beasts of the open land are still bound as before.', 'What you tame is yours: it gets a name, follows you (three at a time, the rest wait at your den), fights whatever comes at you or at it with its own blows and, every few seconds, a great blow that throws back everything round it; ranged ones shoot. It grows on what it kills, level by level, and never falls far behind you. Beaten, it limps off and is back the next day. It follows you into the dungeons and the worlds beyond the gates too.', 'The Animals page (U) lists your tamed beasts — level, kills, whether it is with you, resting or at your den — to call, send to the den or release. You can keep twelve.', 'Your saved game carries on as it was.'] },
    { v: '0.8.7', items: ['The whole map is revealed. Every coast, forest, road and region of the world is drawn on your map (and the small map in the corner) from the start, with every town, dungeon (its name, level and floors), camp, lair, landmark, wonder and ruin, the hidden places too — caves, shrines, wrecks, stone circles, hermits\' huts, buried caches — and the deep woods and the gates. Prefer to explore? The "Whole map shown" button on the map switches back to only what you have walked, and back again.', 'A finer map: the land is painted at four times the detail, colours run into each other instead of in squares, hills and mountains are shaded by the light from the north-west, coasts are inked with the shallows lighter and surf on them, every tree in the woods is dotted in with its shadow, the deep woods are dark and ringed, and the trails through the forests show as pale paths.', 'Roads are drawn as roads — a pale verge under a brown way — sharp at every zoom. The gates\' menace is ringed in red. Region names are spaced capitals that no longer pile on top of each other or of the towns and dungeons; at the full view the dungeons\' names wait until you zoom in, so the map stays readable.', 'Find a place: type part of a name (a town, a dungeon, a region, a deep wood…) and click the result to go there. A new button shows the whole world at once. The chart has the world\'s name in a cartouche and darkened edges like old paper.', 'You can mark and be guided to any spot on the map now, not only land you have walked.', 'Your saved game carries on as it was.'] },
    { v: '0.8.6', items: ['Forests are easy to walk now. Every forest of any size has trails worn through it — light paths of bare earth, clear of trees, that wind in from the meadows and roads to its heart — and you go faster on them than anywhere off a road. Off the trails, the woods slow you less than they did.', 'The deep woods. The greatest forests of the land (two or three of them, grown thick where they were thin) each hold a wood that is not like the others: dead and twisted trees hung with moss, glowing mushrooms, bones, brambles, antlered skulls on poles and iron cages hanging from the boughs. The light goes as you step under its trees and the air turns green and close; eyes watch you from between the trunks and go out when you come near; you hear crying, and growling, and a hunting horn somewhere far in. At night it is very dark indeed. Each is marked on the world map, with what lives in it.', 'What lives there is the strongest in the land outside the gates, and worse the deeper you go: its fringe, its deep and its heart. For a new adventurer the fringe holds beasts of level 70 and the heart of level 300; as you grow, so do they.', 'Six new beasts, each with a body and ways of fighting of its own. The Gloamstalker, long and low with a mask of bone, goes out like a candle and comes back behind you (the ground darkens where it will strike) and hamstrings you. The Hollow Man, skin over bones with a stag\'s skull for a face, screams — and your legs run you away from it — and tears into you, drinking what it tears out. The Barkhulk, an oak woken angry, sends rings of roots out through the ground, closes its bark to heal, and throws logs. The Weeping Bride drifts, wails a cone of cold that slows you, vanishes and appears again, and makes hands come up out of the ground to hold you. The Bough Widow hangs unseen over the trails and drops on you — watch for the shadow — spits webs that hold you fast, and brings her brood. The Briarwyrm goes down among the roots and comes up under you, and looses fans of thorns that make you bleed.', 'At the heart of each deep wood, on a throne of antlers, waits its lord — the Erlking, the Antlered King: the horn of the Wild Hunt sends ghostly riders down lanes across the ground, his hounds come out of the dark, thorns close round you, and at half his life the whole Hunt rides. Kill him for two legendary pieces and great renown; he comes back in time.', 'Along the trails of the deep woods lie the remains of those who went in before you — bones, an abandoned camp, a cage — with what they carried: gold, epic or legendary gear, and the parts of what killed them. New materials: gloamhide, black antler and heartwood.', 'The Journal\'s guide has a page on the deep woods (it also no longer fails to open while there are great beasts in the world).', 'Your saved game carries on as it was: its forests get their trails and its deep woods the first time you load it.'] },
    { v: '0.8.5', items: ['The National Guard now works in the whole realm, not only at its gates.', 'Auxiliaries: the Guard takes the best soldiers and town guards of the realm as its auxiliaries — you know them by their Guard-blue capes. They train harder than anyone (they rise further and faster), and the best of them, reaching level 150, take the full oath.', 'Patrols: two or three auxiliaries ride the roads near you and fight whatever threatens them. Stop one and ask for news.', 'Garrisons: the Guard posts auxiliaries to the towns in most danger — near a named monster\'s claimed land, after a raid, with a loose beast or a hungry titan close by. A garrison breaks raids far more often, saves lives when a titan falls on the town, and drills the town\'s own guard while it is there. Any town can also pay the Guard for one (notice board → Spend your coin).', 'Breaches: now and then something of level 150 and more gets out of a gate and makes for the nearest town. A warden comes down from the gate to run it down, with auxiliaries. If you are near, you see it: the beast turns on the warden, not on you — keep clear if you are below level 150, or help bring it down if you are strong enough. Loose beasts are marked on the world map.', 'Culls: a named monster that grows too strong for the realm, or too powerful, is hunted down by a warden before it can empty a province.', 'Contracts: ask any auxiliary or warden "Does the Guard have work for me?" — the head of a named monster for coin, marked on your way. Sworn members get orders (loose beasts too), earn merit, draw from the armoury (legendary gear at your level for 4 merit) and are paid a weekly wage.', 'The Journal has a new page, The Guard: loose beasts, the wardens, the garrisons, the auxiliaries, what they have done lately, and your own standing and contract.', 'Your saved game carries on as it was.'] },
    { v: '0.8.4', items: ['More to do with your money. Every notice board has a new "Spend your coin" page, with what your crowns can do in that town.', 'Train with the town\'s master-at-arms (its best guard or soldier): a hard day in the yard gives about a third of a level\'s experience and sharpens your blade, shield and bow skills. Once a day, and the price grows with your level.', 'Arm and drill the town guard: every guard jumps half the way to what they could be, and for a month after they keep rising twice as fast and hold off raids better. Once a week.', 'Pay for a palisade, a watchtower or a granary where a town has none. Walls make named monsters\' raids break on the town far more often and hold longer in a war; a watchtower makes the roads near it safer; a granary feeds the town when hunger comes. The town remembers who paid for them.', 'Throw a feast for the whole town (once a week): unrest falls, hunger eases, everyone there thinks better of you, and you leave well fed.', 'Put a price on a named monster\'s head. With a bounty on it, the realm\'s fighters go after it soon and in a company instead of alone, from further away. Kill it yourself and you take your coin back.', 'At a shrine or temple: buy a blessing for three days. Valour (+15% to every blow, arrow and flame), Warding (15% less from every blow), Swiftness (8% faster) or Fortune (merchants pay 15% more).', 'At a smithy: commission a masterwork. The smith makes you an epic or (from level 20) legendary weapon, bow or armour at your own level, always with a property of its own. If it is better than what you have, you take it up at once.', 'Your saved game carries on as it was.'] },
    { v: '0.8.3', items: ['Selling gear is quick now. At any market, "Gear you do not use" has one-click sales — everything weaker than what you use, all the Common and Fine pieces, or everything — each showing how many pieces and what they fetch before you click.', 'Or tick just the pieces you want to part with (with Tick all, Tick the weaker and Untick all) and sell them together; the button shows the running total.', 'Every piece says whether it is ▲ better than what you use, ▼ weaker, or about the same, and the weaker ones are listed first.', '🔒 Keep a piece (at the market or on your character page) and no sale in bulk will ever take it. What you wield, wear and shoot with is never sold.', 'Tick "Sell gear weaker than yours by itself" and every market you come to buys your weaker pieces as you arrive.', 'Your saved game carries on as it was.'] },
    { v: '0.8.2', items: ['The realm rises with you. Everyone now has a level they are reaching for, set by their trade, their ambition, their talent and the age the realm has reached (your level — or, early on, what time alone makes of it): soldiers and guards aim for half to three-quarters of your level, hunters, wanderers and outlaws for about half, captains and champions higher, and the rival adventurers for your own level; ordinary townsfolk stay modest. Each day they climb part of the way, the ambitious faster — so as you grow, so do they, all the way up the levels.', 'People are no longer held at level 150: they can rise as high as you can (1500). The rivals\' old cap of 15 is gone. Those who join the National Guard still train beyond the gates, but slow down once they are well past the realm\'s age, so the very best of the realm stand at about your level, not far beyond it.', 'Out in the open, what lives in the land grows with the age too: once you have outgrown it, wolves, trolls and the other things that roam meet you at half to nine-tenths of your level (worth more experience for it). Dungeons keep the levels they are known for — but those you have long outgrown slowly fill with stronger things. Named monsters close the gap to you in bigger steps.', 'An older world catches up at once: the first time you play it now, its fighters take most of the way they would have climbed while you grew — people around you show their new levels within a few seconds.', 'Your saved game carries on as it was.'] },
    { v: '0.8.1', items: ['Beyond the Rift is remade. Its halls are slabs of obsidian flagstones adrift in the void, seamed with violet light that pulses here and there; their edges break off into an abyss of stars and slow nebulae far below, where shards of rock drift and turn. Spires of black glass and violet crystal stand along every edge, tears in the air glow at the back of the halls, motes of light rise through it all, and violet fire burns in iron braziers. Obelisks and crystal clusters stand in the halls, and on the last floor the Hollow King waits by a throne of black glass.', 'Its monsters have shapes of their own instead of being coloured townsfolk: skeletons are real skeletons (skull, ribcage, spine, bony limbs, a rusted blade or a bow and a ragged hood), wraiths are hooded shrouds with clawed hands and a face of darkness that drift above the floor trailing ghost-mist, cultists wear long robes with gold trim and a sash, their faces deep in their hoods, with gnarled staves crowned in violet light, stonelings are hulks of cracked rock with crystals growing from their backs and glowing seams, and the Hollow King is a crowned skull in dark plate and a tattered cloak, with a sceptre of void-light.', 'Monsters are no longer flat colour: bone is pitted and cracked, cloth is woven and creased and dirty at the hem, stone is split into plates, metal is brushed and scratched with rust in its seams, leather is grained, ghost-stuff drifts and glows and shows through, and crystal glows. This goes for every monster in a person\'s shape too — goblins, ghouls, shamans, outlaws, the barrow dead.', 'Your saved game carries on as it was.'] },
    { v: '0.8.0', items: ['Monsters and the people of the world now grow through their fights, and want to be stronger.', 'In a fight, everything that fights is learning: monsters, wolves, outlaws, guards and townsfolk gain from every blow they land and every blow they take and live through — most of all from you, and from anything stronger than they are — and from every kill. Enough of it and they grow a level then and there (▲): more life, harder blows, sharper wits. Whatever keeps hurting them, they learn to meet: shoot the same goblin again and again and it learns to turn your arrows.', 'Each kind of monster remembers how you fight it. Fight skeletons with arrows and they come at you hardened against arrows; every fight it has with you (and above all every time it beats you) makes the next one of its kind a little stronger. Change how you fight them. The Journal\'s new Rising powers page shows what each kind has learned of you.', 'A monster that beats you, kills someone, or grows twice in one fight takes a name — Snash the Unbroken, Velgar the Cunning — and lives on in the world after you leave. Named monsters want more: day by day they grow (the further behind you, the harder they drive themselves), learn arts of their own (a charge, a slam, regeneration, venom, fire, calling their kin) or harden against how you fight, gather a warband, claim a stretch of country as Chieftain, Warlord or Overlord (where the monsters of their claimed land grow bolder), raid the towns near them, and fight one another for followers.', 'The ones that have met you remember: they come looking for you, at the head of their warband, and tell you so. Kill one and it drops something good, and its name is told across the realm. Some stay in their dens and wait for you on their floor.', 'People want it too: every fighter in the realm trains and grows, the ambitious faster, more so while you are far ahead of them. Each town has a champion, and the best of them go out after the named monsters — some come home famous, some do not come home. Guards and townsfolk who fight beside you keep what they learn.', 'All of it is on the Journal\'s Rising powers page: the named monsters (level, where they are, what they want, what they have learned, what they have done), what each kind has learned of you, and the realm\'s best fighters.', 'Your saved game carries on as it was: the world starts growing from where you are.'] },
    { v: '0.7.9', items: ['The weather changes naturally now. Clouds gather before the rain sets in, the rain starts as a few drops and builds over half a minute, then eases off before the sky clears; fog rolls in and lifts; the light, the colour of the sky and the sound of the rain all follow. Where one region\'s weather meets another\'s, they blend into each other instead of switching at a line.', 'Nothing walks through things any more. Your dragon or great beast has a body as big as it looks — chest, haunches, neck and tail — and trunks, boulders, walls, tents and water stop it as they stop you; it steps round them.', 'A dragon uses its wings for that: when a wood or a wall of rock is in its way it takes off and flies over, always above the tree tops and roofs, and comes down only in a clearing big enough for it. If you are deep in the woods, it circles above you until there is a clearing near you to land in. Flying with you on its back, it stays above the trees too, and when you land (V) over a forest it glides down to the nearest clearing.', 'In a fight your beast now uses all of its own arts, as it sees fit: whatever hits a crowd when there is a crowd, what pins down one great foe, what blinds or scatters what is on top of you when you are hurt — and its greatest art (Meteor Storm, Skybreak, Earthsplitter…) when you are in real danger. A dragon with no room to fight on the ground fights from the air and calls its arts down from there. (Arts that would raise more foes are the only ones it leaves alone.)', 'Walking through woods: you no longer snag on every trunk. You slide round trees and rocks instead of stopping dead, your step bears round a trunk that is square in your way, and if you push into a thicket the game finds the way through it a few steps ahead in the direction you are going. On horseback too.', 'Your saved game carries on as it was.'] },
    { v: '0.7.8', items: ['Flying: your dragon\'s neck no longer stays stuck turned to one side. Its head now leads into every turn you steer, comes back straight when you fly straight, glances at whatever catches its eye below, looks about it when you let go of the reins, lifts as it climbs and drops as it dives.', 'New warnings on the ground before a blow lands. Instead of flat boxes, each one is a glowing shape lying on the land (following hills and slopes) with a bright rim and a dark inner edge so it stands out on any ground: a charge sweeps out across it from the attacker as the blow winds up, with a bright front showing how close it is; chevrons run the way the blow will travel (rings close in on a circle); it pulses faster and faster as the moment comes; and when the blow lands it flashes and fades. Lunges and sweeps are now rounded lanes instead of rectangles.', 'Your saved game carries on as it was.'] },
    { v: '0.7.7', items: ['Fights feel alive. Every blow lands with a bright flash and a spray of sparks thrown the way you struck, and blows now have weight: what you hit spills what it is made of — blood from flesh, chips from bone, grit from stone, gobbets from slimes, wisps from spirits — which flies, falls, bounces and leaves marks on the ground.', 'Each element hits its own way: fire throws embers and smoke and scorches the ground; frost bursts into shards and cold mist and leaves rime; lightning arcs crackle from the wound; venom splashes green; void and magic implode in a swirl.', 'Heavy blows, dives, quakes and critical hits ring out with a shockwave and a flash of light that lights up everything nearby.', 'Sword swings are now a sweeping arc of light that follows the blade, bright at its leading edge.', 'Fireballs burst into a ball of fire, a rising column of smoke and a shower of bouncing embers, and leave a scorch mark. Fireballs and spells glow and light the ground as they fly; arrows leave a faint trail.', 'Dragons\' and beasts\' blows and breath carry their element: a fire dragon\'s strike sets embers flying and scorches the earth, a frost one leaves the ground white, a venom one leaves slime, and a heavy stomp cracks the ground.', 'When something falls, it collapses in a spray and a puff of dust and leaves a mark where it lay. The marks of a fight fade after a while.', 'Your saved game carries on as it was.'] },
    { v: '0.7.6', items: ['The dragons now have skeletons. Each is one smooth skin over 31 bones: a spine running from snout to tail-tip (three bones in the neck, six in the tail), legs that bend at knee and ankle, and wings that fold at shoulder, elbow and wrist. Nothing moves as a rigid block any more.', 'They move through their whole body: the spine curves into a turn, the neck carries the head in an easy arc and bobs with the stride, the tail sways in a travelling wave and trails behind, legs lift and bend as they step, and the chest rises and falls as it breathes.', 'On the ground the wings fold up properly at elbow and wrist along the back; in the air each wingbeat rolls from shoulder to fingertip, and the legs draw up under the body.', 'Resting, it lies down with its legs folded under it and its tail curled round. Turning its head to look, the whole neck turns, not just the head.', 'A finer build too: deep chest, slim waist and strong haunches, a proper shoulder for each wing, frills of skin behind the jaws, and nostrils.', 'Your saved game carries on as it was.'] },
    { v: '0.7.5', items: ['Your dragon (or great beast) is now a partner with a mind of its own, not a statue that trails behind you.', 'It moves like an animal: it turns in arcs, gathers speed and eases to a stop, matches your pace — ambling, trotting, loping to catch up — and a dragon flies after you over any distance and comes down beside you. It looks at what catches its eye: you, the way you are going, anything moving nearby.', 'When you stop it finds itself things to do: it settles beside you and keeps watch, wanders off to sniff at something, stretches its wings with a yawn, lies down to rest if you linger (sooner at night), or — a dragon — takes a turn round the sky above you before landing again.', 'It gets hungry: when it is, it hunts the deer and hares nearby, drops on them or runs them down, and eats its kill.', 'In a fight it thinks: it goes first for whatever is hurting you, then for what you are fighting; it roars and fights harder when you are badly hurt; a dragon takes to the air against a crowd (or a foe it cannot reach) and strafes it with breath, rains fire or dives; badly hurt itself, it pulls back out of reach to recover, then comes back in. After a win it may roar.', 'It greets you when it comes and when you come back to it, head low. Stroke its neck (E) for a moment together.', 'A bond grows between you — riding, fighting and time together, a hand on its neck. The closer it is, the nearer it keeps and the harder it guards you. The Animals page (U) shows its bond, whether it is hungry, and what it is doing.', 'On the wing with you it has a will too: it looks at what is below, roars at another dragon, and if you let go of the reins it flies on by itself in long lazy circles.', 'Your saved game carries on as it was.'] },
    { v: '0.7.4', items: ['Flying on a dragon is all new. Mounting (V) is a take-off: the dragon crouches, springs, and climbs on great wingbeats with a burst of dust below.', 'Dragons now fly much higher — about twice as high as before — and you choose your height: Space climbs (up to very high), Ctrl goes lower. It keeps that height over the land and rises early for the hills ahead.', 'Real flight: the dragon has weight. It banks into its turns (tighter when slow, wider when fast) and slides a little through a hard one, climbing costs it speed and diving gives it, and when you let go it glides on with its wings held out instead of stopping dead. Shift is a hard sprint on full wingbeats.', 'You sit astride its back and lean with it — low over its neck at speed. A soft shadow on the ground below shows how high you are, the view opens out with height and speed and leads the way you are flying, and clouds drift past up high. You no longer turn see-through while flying.', 'Coming down (V) is a proper landing: it sheds its speed as it descends, flares with its wings and sets down in a cloud of dust, and you climb off beside it.', 'Your beast keeps out of your way: when it follows you it stays a body\'s length off on the far side of you from the camera, and in a fight it picks a place beside the foe that is not on top of you or between you and the view. If its bulk still comes over you, it turns see-through until it moves.', 'Your saved game carries on as it was.'] },
    { v: '0.7.3', items: ['A clearer world. The ground is no longer soft washes of colour: town squares are laid with cobbles and mortar, roads have pebbles, fields have furrows, sand has wind ripples, bare rock is cracked into plates, ruins have flagstones, and grass has little tufts — all drawn crisply, and fading out in the distance so they never shimmer.', 'Roofs have rows of shingles that catch the light, so a town reads sharply from above.', 'A fine dark line now traces where one thing stands in front of another — people, beasts, trees and walls stand out cleanly from the ground behind them (Medium and High).', 'The soft blotchy patches that used to cover the ground are much fainter.', 'Your saved game carries on as it was.'] },
    { v: '0.7.2', items: ['A sharper picture. The world is now drawn at your screen\'s own sharpness: on a laptop at 125–150% or a 4K monitor it used to be drawn at a lower resolution and stretched, which is what made it look soft. Medium draws up to 1.5 pixels per screen pixel, High up to 2, and Low no longer draws below your screen\'s resolution.', 'Names, labels, signs and speech over people\'s heads are always drawn at full sharpness, whatever the quality.', 'A sharpening pass makes edges crisp (without bright or dark rims), and stronger if the game has had to lower its resolution to keep up.', 'Crisper shadows (twice the detail on Medium and High), a tighter glow round lights, and almost no film grain.', 'When the game has to work less to stay smooth it now gives up ambient occlusion and glow first, and lowers the resolution only last — and never below one pixel per screen pixel.', 'The dragons are no longer boxy. Every dragon has a new body, made in Blender as one smooth form along its spine: a long curved neck and tail with a coloured belly, a horned head with brows, glowing eyes, teeth and a jaw that opens, clawed legs, spines down its back in its own colour, a spade at the tail tip, and real wings — skin stretched between long finger bones, scalloped at the edge. On the ground the wings fold back along the body; in the air and when it roars they open wide.', 'The great serpents (Mawtide, Grimmaw) are rebuilt the same way: smooth coils tapering to a pointed tail, a fin down the back, and a horned dragon\'s head.', 'Your saved game carries on as it was.'] },
    { v: '0.7.1', items: ['Smooth at speed: galloping, and above all flying on a dragon, no longer stutters or hitches.', 'Only the land the camera can actually see is drawn now (it used to draw everything around you, out of sight too), and the trees, crops and stones further off use plainer far versions — about a quarter of the triangles of 0.7.0, with the look up close unchanged. Fields of crops in particular were far heavier than they needed to be.', 'The land ahead of you is built before you get there, a few milliseconds a frame, and what you have just passed is kept a while; towns, hidden places and people coming into sight are put together over several frames instead of all in one.', 'No more pauses the first time something new appears (a dragon fading in, a spell, a shrine): every kind of shader is now built in the background when the world loads, and kept.', 'The route planner no longer re-plans the whole way every few seconds while you fly (the line just points the way), and plans faster on the ground.', 'Shadows no longer crawl and shimmer as you move, and your own shadow keeps up with you at speed. The sun\'s shadow is no longer switched off at night (that rebuilt every shader in the world at dusk and dawn — a long stall).', 'The camera keeps up better at speed, and doesn\'t bob over every hill passing under a dragon.', 'Automatic resolution now judges by the typical frame, not by a few slow ones while new land streams in, and changes far less often (each change was itself a small stall).', 'Your saved game carries on as it was.'] },
    { v: '0.7.0', items: ['A new look. Every model has been rebuilt in Blender with bevelled edges, rounded forms and smooth shading — trees, people, beasts, buildings and dragons are no longer faceted.', 'The picture is finished like a modern engine\'s: lanterns, fires, spells and windows at night glow (bloom); ambient occlusion grounds everything; a filmic tone curve and colour grading follow the hour and the weather (warm dusk, cool night, grey storms, amber interiors); the sky lights the world, and metal catches it; ground, stone and walls have their own grain instead of flat colour.', 'It keeps the game smooth: when frames start to slow, it lowers its resolution a step at a time (and then drops the costliest effects), and climbs back when it can. Quality in the Esc menu: Low (fastest), Medium (shadows, glow, smooth edges, grading), High (plus ambient occlusion and finer detail).'] },
    { v: '0.6.0', items: ['Everything in the world is more aware now. Enemies, townsfolk, wolves, your companions, your bound beasts and the Guard read the ground: every marked blow, titan art, poison pool or rolling boulder is a place not to be, and those who see it coming step out of it — your companions and beasts do it for you.', 'They watch what flies at them: shields come up to meet arrows, and the quick step aside from arrows and fireballs (the clever ones dodge some of yours; the mindless never do). A quick enemy may step back out of a heavy blow you hold in its face.', 'Enemies choose their target — whoever hurt them most, whoever is nearly down, the healer first — and stick with it. Archers aim where you are going, and chasers cut you off.', 'Badly hurt with friends at hand, an enemy falls back behind them before coming again. And the ones with voices call out what they mean to do: "Move!", "Get the healer!", "Cover me!"', 'How much each notices depends on what it is: a slime almost nothing, a sergeant most things, a warden of the Guard everything. Titans fight their own way.'] },
    { v: '0.5.5', items: ['Levels, gear and power now agree with each other everywhere. Danger labels (Easy, Hard, Deadly, Run) and experience measure the gap in steps of a tenth of your level, so a foe forty levels above you at level 300 reads as Deadly — as four levels does at level 10 — instead of everything a few levels apart reading Run.', 'Fire (Q) and the staff\'s bolt now grow with your level as a weapon does: they used to fall far behind your sword (at level 150 a flame took 40 casts to kill what a blade killed in two).', 'Companions past level 12 grow on the same curve as you: they no longer fall behind and die in one or two blows at high levels.', 'Smith\'s work is made for you: forged weapons and crafted armour (Dragonscale mail, the Beastlord\'s mantle…) match your level and the quality of their parts, honing adds a twentieth of the piece, and star-iron adds a twelfth. Story and ambition rewards (Crownbreaker, the Champion\'s Blade) match your level when you earn them.', 'Titans keep their place against you at every level (Gorehorn two steps above you, Nyxathar twenty-one), and a bound beast fights two steps above your own level.'] },
    { v: '0.5.4', items: ['Y now switches between your animals: each press calls the next one — your horse, then each of your beasts in turn — and sends the one with you away. (A beast that is resting is skipped.) U still opens the Animals page.'] },
    { v: '0.5.3', items: ['When you call a beast, your horse goes home (if you are riding, you step down first) and stays away until you whistle for it with V — it comes back from wherever it went.', 'A new Animals page (U, or Journal → Animals) shows every animal under your control: your beasts with their life, level, where they are, what they can do for you and buttons to call, send away or set them free; your horse with its trust, wind and whereabouts, and buttons to whistle for it or send it home; and your dog. Your character page now points to it.'] },
    { v: '0.5.2', items: ['The dragons and great beasts are far stronger now, and never beneath you: each one\'s level rises with yours (from a few levels above you up to some thirty), with more life and harder blows.', 'Every titan has arts of its own — two or three each, plus a nature of its own, like Gorehorn\'s Ironhide (strike it from behind), Rimefang\'s ice armour (fire breaks it) or Solgrim\'s Rebirth. Thirty arts in all: rings of ice with one way out, blizzards that chase you, poison clouds with a few safe circles, lightning that follows you, sweeping sunbeams, rifts that drag you in, boulders rolling from every side, burrowing serpents that burst up under you, and more.', 'Fights have three phases: enraged at two-thirds of its life (quicker, new arts), and desperate at one-third, when it unleashes its greatest art — Meteor Storm, Absolute Zero, Plague Cloud, Skybreak, Supernova, The End of Days, Earthsplitter, Tempest, Tidal Venom, Cataclysm. The name of each art appears as it begins, and the ground shows where it will strike.', 'Your bound beasts use some of their arts for you.'] },
    { v: '0.5.1', items: ['ECHO is now 3D only. The classic 2D view has been removed, along with its switch in the Esc menu; the Quality setting is always there for slower machines.', 'The person you talk to is shown in a portrait drawn from their own 3D model, in their own clothes, hair and gear.', 'If a computer or browser can\'t give the game 3D graphics, it now says so plainly instead of starting. Your worlds and progress are untouched.'] },
    { v: '0.5.0', items: ['Dragons and great beasts now live in the open world: ten titans, each one of a kind, from Gorehorn (level 26) to Nyxathar the End of Days (level 1400). Six are dragons that fly — fire, frost, venom, lightning, sunfire and void — and four are great beasts that walk. Each has its own range with its young, its prey and its roost; dragons circle by day and sleep at night. They are on the map and in the guide (J).', 'They fight like nothing else: dragons take to the air out of reach of your blade and strafe, rain their element and dive on you, then land and fight with jaws, tail and breath. Every attack is marked on the ground first. The greatest of them raid and burn towns when no one stands against them.', 'Beat one down and bind it (E): you can keep four. A bound beast follows you and fights for you (Y calls it or sends it away; your character page lists them). Stand by a bound dragon and press V to fly — WASD to steer, Shift to fly fast, V to land. Your progress is untouched; the titans simply appear in your world.'] },
    { v: '0.4.2', items: ['No more sudden deaths out of nowhere: a single blow can no longer take you from a healthy life bar to the ground. You are left standing on a sliver of life for a moment (once every little while), so you can get away, eat or use herbs.', 'You see what each hit takes: a pale piece of your life bar drains away after it. Below a third of your life the bar beats and the edges of the screen go red.', 'When you fall, you are shown what brought you down — who hit you, with what, and how much of your life each took.'] },
    { v: '0.4.1', items: ['Lock-on (R) no longer picks your trainer or any warden of the National Guard, and your blows, arrows and fire pass them by — they only ever pick out the beasts.'] },
    { v: '0.4.0', items: ['Three gates now stand alone in the wild, marked on every map and visible from far off. Their menace kills anyone below level 150 (rings on the ground show where it hurts and where it kills; below 150 the navigation goes round them).', 'Beyond each gate is a world of its own: the Ashen Expanse, the Sunken Choir and the Rotwood. Their beasts run from level 150 at the door to 1500 at the heart, where a sovereign waits. Each kind of beast fights in its own way, and they hunt each other, growing stronger on what they kill.', 'The National Guard holds the gates: six wardens, each strong enough for level 1500, each with arts of their own. At level 150, talk to one and take the oath. Your warden then takes you through, leads you to beasts your size, keeps you alive and teaches you. Townsfolk who reach 150 can join too.', 'Levels now go up to 1500, with eight new ranks past the Undying.'] },
    { v: '0.3.8', items: ['Where to? (N): everything you could head for in one list (promises, jobs, cases, the story, dungeons your size, your marks). Pick one and a golden trail on the ground leads you there by the best way: roads and bridges, round lakes, cliffs and walls, never into a dead end. The top line tells you the next stretch ("follow the road south", "through the woods") and the distance left, and the route shows on your maps. New promises and jobs are followed for you if nothing else is.', 'A calmer screen: repeated notices are folded together, routine ones wait behind important ones, banners only greet you on first visits or after long absences, town news arrives as one line, the weather is mentioned once a day, and only the people who matter speak aloud at once.'] },
    { v: '0.3.7', items: ['Smarter pathfinding for every creature and person: they look ahead and steer round trunks, rocks and walls, plan routes only through gaps their body actually fits, notice when they stop getting closer and plan a way round, and avoid the spot that stopped them. Wolves chasing through woods now get through about four times as often; big creatures like trolls find their way through towns and rocky ground.'] },
    { v: '0.3.6', items: ['Send word to your old companions: on your character page (K), everyone who once rode with you can be reached by a runner (3 crowns) — ask them to come back and fight beside you (they ride to find you), to send supplies, or just send your regards. Their answers arrive as letters.'] },
    { v: '0.3.5', items: ['Anyone carrying a weapon now fights back when attacked — a farmer you armed will stand and cut down the wolves instead of running.', 'Gear counts properly for townsfolk: their blows come from their weapon\'s own damage (shaped by their skill), as yours do, and their strength updates as soon as they put something new on.'] },
    { v: '0.3.4', items: ['People now look like what they wear, the same way you do: the colour and glow of their blade, axe, spear, staff or bow, and their armour\'s colours, helm, shoulder plates and crest — in 3D and in 2D.', 'Talking to someone shows the gear they wear, with pictures, names and stats, and their level.'] },
    { v: '0.3.3', items: ['Give gear you don\'t use to anyone, free: "Give away…" on any spare piece in your character page (K), or tell someone "I have gear I don\'t use — take it". ★ marks who would wear it; anyone else passes it to whoever in town needs it.', 'In a town, "Share all spare pieces" hands everything you don\'t use to the people who need it most. People remember, and word of it spreads.'] },
    { v: '0.3.2', items: ['Updates now arrive completely by themselves: each new version is published automatically, downloaded in the background, and switched to on the title screen.', 'Fixed a rare crash when a great beast roared before the sound had started.'] },
    { v: '0.3.1', items: ['Guards, soldiers, outlaws and townsfolk now size up a foe before they fight: its level, gear, health and healing against their own and their friends\'. Good odds, they fight; poor odds alone, they shout for help, hold back out of reach and go in together once enough have gathered; hopeless, guards keep their distance and send for more while outlaws and townsfolk run.', 'Seasoned or brave townsfolk answer a call for help and fight beside the guards when together they stand a chance.'] },
    { v: '0.3.0', items: ['Townsfolk go delving too: guards, hunters and the bold go down into dungeons and caves (alone or with friends), come back stronger and wear the weapons and armour they find. Some don\'t come back.', 'Everyone has a level now, and seasoned delvers hit harder and last longer. Ask anyone "How strong are you these days?" — and give them gear from your pack.', 'The guide (J) lists the townsfolk who delve, with their level and gear.'] },
    { v: '0.2.9', items: ['No more dungeon floors walled off by chests, stairs, boulders or pillars: every room, iron door, stair and chest can now be reached.'] },
    { v: '0.2.8', items: ['Your hero no longer dies for good: a fall costs a few days and some coin, never your level or gear. (Legacy, where heroes die for good, is now a choice in the Esc menu.)'] },
    { v: '0.2.7', items: ['Updates now install themselves: the app downloads each new version in the background and plays it the next time you open it, or at once with Restart now.'] },
    { v: '0.2.6', items: ['When you fall to beasts or monsters, you wake in a town with a dungeon of your level close by, and can head straight for it.'] },
    { v: '0.2.5', items: ['Horses no longer get stuck against trees, rocks or the water\'s edge: a wedged horse works itself free, steers round trunks and boulders, and picks its way through thick woods at a walk.', 'When you mount or whistle, your horse stands somewhere with room to move.'] },
    { v: '0.2.4', items: ['The title screen shows your version in a clear badge: green when you have the newest, gold with a download button when a new one is out.', 'If an update is out, you are told each time you enter a world.'] },
    { v: '0.2.3', items: ['The app tells you when a new version is out, with a button to download it, and shows what changed after you update.'] },
    { v: '0.2.2', items: ['Every town of the old island has an easy starter cave nearby (Lv 1–3), shown on the map from the start.', 'The guide (J) lists dungeons for your level: the best floor for you in each, and a Guide me there button.'] },
    { v: '0.2.1', items: ['Text no longer piles up over the HUD in smaller windows.'] },
    { v: '0.2.0', items: ['Choose any floor you have reached at a dungeon door.', 'Saves are kept with a backup copy; Export and Import world work in the desktop app.'] }
  ];

  const cmp = (a, b) => {
    const pa = String(a || '0').split('.').map(n => parseInt(n, 10) || 0), pb = String(b || '0').split('.').map(n => parseInt(n, 10) || 0);
    for (let i = 0; i < Math.max(pa.length, pb.length); i++) { const d = (pa[i] || 0) - (pb[i] || 0); if (d) return d > 0 ? 1 : -1; }
    return 0;
  };
  const store = {
    get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
    set(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* ignore */ } }
  };

  const Up = ECHO.Updates = {
    CHANGES, cmp,
    build: CHANGES[0].v,   // (the version this build is, for the web version too)
    state: 'idle', // idle | checking | current | available | error
    current: null, info: null, news: null, toasted: false,

    native() { return window.echoNative && window.echoNative.checkUpdate ? window.echoNative : null; },

    async init() {
      const N = Up.native();
      if (!N) return;
      try { Up.current = await N.version(); } catch (e) { return; }
      const last = store.get('echo.lastVersion');
      if (last && cmp(Up.current, last) > 0) Up.news = CHANGES.filter(c => cmp(c.v, last) > 0 && cmp(c.v, Up.current) <= 0);
      else if (!last) {
        // first run of a version that knows about this: if worlds exist, this is an update
        try { const metas = await ECHO.Save.list(); if (metas.length) Up.news = CHANGES.filter(c => c.v === Up.current); } catch (e) { /* ignore */ }
      }
      if (Up.news && !Up.news.length) Up.news = null;
      if (!Up.news) store.set('echo.lastVersion', Up.current);
      Up.mount();
      Up.check();
      setInterval(() => Up.check(), 3600 * 1000);
      // tell a player who is in a world, once per world entered
      let shownFor = null;
      setInterval(() => {
        const g = ECHO.Game, UI = ECHO.UI;
        if ((Up.state !== 'available' && Up.state !== 'ready') || !g || !g.world || !UI || !UI.toast || UI.paused()) return;
        const key = g.world.id + '|' + Up.info.latest + '|' + Up.state;
        if (shownFor === key) return;
        shownFor = key;
        UI.toast(Up.state === 'ready'
          ? `⬆ ECHO ${Up.info.latest} has downloaded. It switches over when you go back to the title screen or next open the game (or now: Esc → Restart now). Your world carries over.`
          : `⬆ ECHO ${Up.info.latest} is out (you have ${Up.current}). Press Esc to download it; your worlds carry over.`, 'legend', 10);
      }, 4000);
    },

    async check() {
      const N = Up.native();
      if (!N || Up.state === 'checking') return;
      Up.state = 'checking'; Up.mount();
      let r = null;
      try { r = await N.checkUpdate(); } catch (e) { r = { error: String(e) }; }
      if (!r || r.error || !r.latest) Up.state = 'error';
      else {
        Up.info = r;
        const newer = cmp(r.latest, Up.current || r.current) > 0;
        // a release still being built (its game file not attached yet): wait and look again
        const fresh = r.date && Date.now() - Date.parse(r.date) < 40 * 60 * 1000;
        Up.state = !newer ? 'current' : r.ready === r.latest ? 'ready' : (r.why === 'no game file' && fresh) ? 'pending' : 'available';
        if (Up.state === 'pending') { clearTimeout(Up._again); Up._again = setTimeout(() => Up.check(), 3 * 60 * 1000); }
      }
      Up.mount();
      Up.autoApply();
    },
    // On the title screen (no world open), a downloaded update switches over by itself.
    autoApply() {
      const N = Up.native();
      if (Up.state !== 'ready' || !N || !N.restart || Up._applying) return;
      if (ECHO.Game && ECHO.Game.world) return;          // never in the middle of play
      if (!document.querySelector('#screen:not(.hidden) .upd-slot')) return;   // only on the title screen
      Up._applying = true;
      Up.mount();
      setTimeout(() => { if (ECHO.Game && ECHO.Game.world) { Up._applying = false; Up.mount(); return; } N.restart(); }, 2500);
    },

    // The little card on the title screen and in the pause menu.
    html() {
      if (!Up.native()) return '';
      const v = Up.current ? 'v' + esc(Up.current) : '';
      let out = '';
      if (Up.news) out += `<div class="upd-card upd-news"><h4>Updated to ${v}</h4><ul>${Up.news.map(c => c.items.map(t => `<li>${esc(t)}</li>`).join('')).join('')}</ul><div class="dim">Your worlds and progress are as you left them.</div><div class="row"><button class="small" data-upd="seen">Got it</button></div></div>`;
      if (Up.state === 'ready' && Up._applying) {
        out += `<div class="upd-card upd-new"><h4>⬆ Updating to v${esc(Up.info.latest)}…</h4><div class="dim">One moment — ECHO restarts on the new version. Your worlds carry over.</div></div>`;
      } else if (Up.state === 'pending') {
        out += `<div class="upd-badge"><b>ECHO ${v}</b> <span>v${esc(Up.info.latest)} is on its way — it will install itself in a few minutes</span></div>`;
      } else if (Up.state === 'ready') {
        out += `<div class="upd-card upd-new"><h4>⬆ ECHO v${esc(Up.info.latest)} is ready</h4><div class="dim">It has downloaded by itself and switches over when you return to the title screen or next open ECHO. Your worlds and progress carry over.</div><div class="row"><button class="small primary" data-upd="restart">Restart now</button></div></div>`;
      } else if (Up.state === 'available') {
        const i = Up.info;
        out += `<div class="upd-card upd-new"><h4>⬆ A new version is out: v${esc(i.latest)}</h4><div class="dim">You have ${v}. Download it and install over this one; your worlds carry over.</div><div class="row">${i.download ? `<button class="small primary" data-upd="download">Download ${esc(i.file || '')}</button>` : ''}<button class="small" data-upd="page">${i.download ? 'Release page' : 'Download page'}</button></div></div>`;
      } else {
        const st = Up.state, s = { idle: 'checking for updates…', checking: 'checking for updates (and fetching any new version)…', current: '✓ up to date — this is the newest version', error: 'could not reach GitHub to check for updates' }[st] || '';
        out += `<div class="upd-badge ${st === 'current' ? 'ok' : st === 'error' ? 'err' : ''}"><b>ECHO ${v}</b> <span>${s}</span>${st === 'error' || st === 'current' ? ' <button class="small linkish" data-upd="check">Check again</button>' : ''}</div>`;
      }
      return out;
    },

    mount() {
      document.querySelectorAll('.upd-slot').forEach(el => { el.innerHTML = Up.html(); Up.bind(el); });
      if (Up.state === 'ready' && !Up._applying) setTimeout(() => Up.autoApply(), 0);
    },

    bind(root) {
      root.querySelectorAll('[data-upd]').forEach(b => b.addEventListener('click', () => {
        const a = b.dataset.upd, N = Up.native();
        if (a === 'download' && Up.info && Up.info.download) N.openLink(Up.info.download);
        else if (a === 'page' && Up.info) N.openLink(Up.info.page);
        else if (a === 'check') Up.check();
        else if (a === 'restart') {
          b.disabled = true; b.textContent = 'Saving…';
          (async () => { try { if (ECHO.Game && ECHO.Game.world) await ECHO.Game.save(); } catch (e) { console.error(e); } if (N.restart) N.restart(); })();
        }
        else if (a === 'seen') { Up.news = null; store.set('echo.lastVersion', Up.current); Up.mount(); }
      }));
    }
  };
})();
